package com.devkanyanta.pos.sale.dto;

import java.math.BigDecimal;
import java.util.List;

import com.devkanyanta.pos.payment.dto.CreatePaymentRequest;

import lombok.Getter;
import lombok.Setter;

@Getter
@Setter
public class CreateSaleRequest {

    private Long customerId;

    private String notes;

    private BigDecimal discountAmount;

    private List<SaleItemRequest> items;

    /**
     * Optional unique id generated by the client (e.g. a UUID). Re-sending a request with the
     * same id returns the already-recorded sale instead of creating a duplicate.
     */
    private String clientSaleId;

    /** Optional id of the device that captured the sale. */
    private String deviceId;

    /**
     * Optional tenders to record together with the sale (split payments allowed), so a
     * checkout is a single atomic call.
     */
    private List<CreatePaymentRequest> payments;
}
